wheelTrigger.source:
function () {
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            if (!this._gameType.isFG && logicResponse.featureDatas.data[0]) {
                //Wheel triggered 
                this._statesModel.changeStateByName(sgigame.BaseGameStates.WF_START);
                this._autoPlayModel.stop();
                sgigame.CommonUIModel.isautoplaying = 0;
            }
            else if (this._gameType.isFG && logicResponse.fsData.triggeredFeatureIndex > 0) {
                this._statesModel.changeStateByName(sgigame.BaseGameStates.WF_START);
            }
            else {
                this._statesModel.gotoNextState();
            }
        }

wheelResult.source:
function () {
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            if (logicResponse.featureDatas.data[0]) {
                //Wheel triggered 
                var triggeredFeatureIndex = parseInt(this._server.getLogicResponse().featureDatas.data[0].attributeData.triggeredFeatureIndex);
                switch (triggeredFeatureIndex) {
                    case 1:
                        console.log("Free spin");
                        if (parseInt(logicResponse.featureDatas.data[0].attributeData.isRetrigger))
                            this._statesModel.changeStateByName(sgigame.BaseGameStates.FG_MORE_FREE_GAME_BANNER);
                        else if (this._gameType.isFG)
                            this._statesModel.changeStateByName(sgigame.BaseGameStates.FG_MORE_FREE_GAME_BANNER);
                        else
                            this._statesModel.gotoNextState();
                        break;
                    case 3: // Upgrade
                    case 4:
                        this._RecoveryType.isGameRecover = false;
                        this._statesModel.changeStateByName(sgigame.BaseGameStates.WF_UPGRADE); //Upgrade
                        console.log("Upgrade");
                        break;
                    case 5:
                        console.log("Wild spin");
                        this._RecoveryType.isGameRecover = false;
                        this._statesModel.changeStateByName(sgigame.BaseGameStates.WS_START);
                        break;
                    case 10:
                        // To be changed.
                        //this._statesModel.changeStateByName(BaseGameStates.WF_CHECK_WHEEL_FEATURE_REMAINING);
                        //this.eventDispatcher.dispatchEvent(new sgigame.JackPotMeterEvent(JackPotMeterEvent.SHOW_WIN_METER));
                        this._statesModel.changeStateByName(sgigame.BaseGameStates.JACKPOT_START);
                        console.log("Jackport");
                        break;
                }
            }
        }

remainingWheel.source:
function () {
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            if (logicResponse.wheelRemaining) {
                if (logicResponse.wheelRemaining.index !== 1) {
                    if (this._gameType.isFG) {
                        if (logicResponse.wheelRemaining.isFGWheel === "Y")
                            this._statesModel.changeStateByName(sgigame.BaseGameStates.WF_START);
                        else
                            this._statesModel.gotoNextState();
                    }
                    else
                        this._statesModel.changeStateByName(sgigame.BaseGameStates.WF_START);
                }
                else {
                    //Goto show all win.
                    this._statesModel.gotoNextState();
                    sgigame.GameConfig.featureTobase = true;
                }
            }
            else {
                //Goto show all win.
                this._statesModel.gotoNextState();
                sgigame.GameConfig.featureTobase = true;
            }
        }

