logicRequest.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [
                this.getStakeEncode(),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
            ];
            var history = this._history.getNextState();
            if (history) {
                encoders.push(new sgigame.HistoryReplaceEncoder(history));
            }
            if (this._statesModel.getCurrentState().stateName === sgigame.BaseGameStates.WF_LOGIC_REQUEST) {
                if (this._metaData.isGaffingEnabled() && !history) {
                    var WheelIndex = prompt("Enter wheel Stop Index", "-1");
                    {
                        if (WheelIndex !== null && WheelIndex != "-1") {
                            var index = WheelIndex;
                            var trigerredWheel = this._server.getLogicResponse().featureDatas.data[0].index;
                            if (this._server.getLogicResponse().featureDatas.data[0].attributeData) {
                                var triggeredFeature = this._server.getLogicResponse().featureDatas.data[0].attributeData.triggeredFeatureIndex;
                                if (triggeredFeature == "3" || triggeredFeature == "4") {
                                    trigerredWheel = parseInt(triggeredFeature);
                                }
                            }
                            var wheelencoder = new sgigame.wheelEncoder(index, trigerredWheel);
                            encoders.push(wheelencoder);
                        }
                    }
                }
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else if (this._statesModel.getCurrentState().stateName === sgigame.BaseGameStates.WS_LOGIC_REQUEST) {
                if (this._metaData.isGaffingEnabled() && !history) {
                    var wildIndex = prompt("Number of wild and wild positions", "4,1,2,3,4");
                    {
                        if (wildIndex !== null) {
                            var wildno = wildIndex.split(',')[0];
                            var wildpos = wildIndex.split(',').map(Number);
                            wildpos.shift();
                            var pos = wildpos.join('|');
                            var wildSpinEncoder = new sgigame.WildSpinEncoder(wildno, pos);
                            encoders.push(wildSpinEncoder);
                        }
                    }
                }
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else {
                if (this._forceModel) {
                    if (this._forceModel.forceSet) {
                        var forceEncoder = new sgigame.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0], this._forceModel.reelData ? this._forceModel.reelData.index : 0, this._forceModel.featureID, this._forceModel.wildIndex, this._forceModel.wildMulValue);
                        encoders.push(forceEncoder);
                    }
                    this._forceModel.featureID = -1;
                    this._forceModel.forceSet = false;
                }
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
        }

