featureParser.source:
function (input, object) {
            var nodeList = input.getElementsByTagName("Feature");
            object.featureDatas = new sgigame.FeatureDatas();
            var randomWildNode = input.getElementsByTagName("RandomWilds")[0];
            if (randomWildNode) {
                object.ramdomWild = randomWildNode.attributes.getNamedItem("positions").value;
            }
            if (nodeList.length > 0) {
                for (var i = 0; i < nodeList.length; i++) {
                    var node = input.getElementsByTagName("Feature")[i];
                    if (node.parentNode.nodeName === "GameResult") {
                        var attributes = node.attributes;
                        var nodeChildren = node.childNodes;
                        var index = parseInt(node.attributes.getNamedItem("index").value);
                        var name = node.attributes.getNamedItem("name").value;
                        var attributeData;
                        //Sakthi
                        if (nodeChildren.length > 0) {
                            if (nodeChildren[0].attributes) {
                                attributeData = sgigame.CustomParser.xmlnameValuePairArrayToObject(nodeChildren[0].attributes);
                            }
                        }
                        var featureInfo = new sgigame.FeatureData();
                        featureInfo.setData(index, name, attributeData);
                        object.featureDatas.data.push(featureInfo);
                    }
                }
            }
        }

featureData.source:
function (index, name, attributeData) {
            this.index = index;
            this.name = name;
            this.attributeData = attributeData;
        }

